98: const prompts = [
99:   { key: 'day', label: 'How was your day?', response: 'It’s been a little better now that we’ve had a chance to talk. Thanks for asking.' },
100:   { key: 'help', label: 'Need a hand with anything?', response: 'That’s sweet of you. I think a little company is all I need right now.' },
