103: function renderChat() {
104:   const r = resident(activeChatId);
105:   if (!r) return `<div class="empty-state">Invite a housemate to start a conversation.</div>`;
106:   const messages = r.messages || [];
107:   return `<section class="chat-layout"><aside class="chat-list-panel"><div class="chat-list-heading"><b>Conversations</b><small>Your housemates are always happy to hear from you.</small></div>${state.residents.map(person => `<button class="chat-person ${person.id === r.id ? 'active' : ''}" data-chat-to="${esc(person.id)}"><span class="chat-person-avatar">${portrait(person)}</span><span><b>${esc(person.name)}</b><small>${esc(person.role)}</small></span><i>♡</i></button>`).join('')}</aside><div class="chat-area"><header class="chat-header"><div class="chat-header-avatar">${portrait(r)}</div><div class="chat-header-copy"><b>${esc(r.name)}</b><small><i></i> Around the house · ${esc(r.role)}</small></div><button class="outline-btn chat-profile-btn" data-action="view-resident" data-id="${esc(r.id)}">View profile</button></header><div class="chat-note">A kind, unhurried conversation. Everyone’s boundaries matter. 🌷</div><div class="message-list" id="message-list">${messages.map(m => `<div class="message-row ${m.from === 'you' ? 'you' : 'them'}">${m.from !== 'you' ? `<span class="message-avatar">${portrait(r)}</span>` : ''}<div class="message-content"><div class="message-bubble">${esc(m.text)}</div><small>${esc(m.time || 'Today')}</small></div></div>`).join('')}</div><div class="suggested-prompts">${prompts.map(p => `<button data-chat-prompt="${p.key}">${p.label}</button>`).join('')}</div><form class="chat-compose-wrap" id="chat-form"><label class="sr-only" for="chat-input">Write a message</label><textarea id="chat-input" rows="1" maxlength="400" placeholder="Write a kind message…" required></textarea><button class="send-btn" type="submit" aria-label="Send message">➤</button></form></div></section>`;
108: }
109: function nowTime() { return new Intl.DateTimeFormat([], { hour: 'numeric', minute: '2-digit' }).format(new Date()); }
110: function sendMessage(text) {
111:   const r = resident(activeChatId);
112:   const message = String(text || '').trim();
113:   if (!r || !message) return;
114:   r.messages.push({ from: 'you', text: message.slice(0, 400), time: nowTime() });
115:   const reply = prompts.find(p => p.key === message)?.response || [
116:     'I’m glad you told me. It’s nice to share the little things with someone.',
117:     'That sounds lovely. Thanks for taking a moment to talk with me. What would you like to do next?',
118:     'I appreciate you checking in. Let’s make today a little gentler, one step at a time.',
119:   ][(r.messages.length + state.day) % 3];
120:   r.messages.push({ from: 'her', text: reply, time: nowTime() });
121:   r.affection = clamp(r.affection + 2); r.mood = clamp(r.mood + 2);
122:   state.coins += 1;
123:   addActivity('💌', `Shared a thoughtful conversation with ${r.name}.`);
124:   save(); render(); showToast(`A lovely moment with ${r.name} · +1 petal`);
125: }
126: function openChat(id) { activeChatId = id || state.residents[0]?.id; setView('chat'); }
127: function openModal(title, content, wide = false) {
128:   closeModal();
129:   const root = $('#modal-root');
130:   root.innerHTML = `<div class="modal-backdrop" data-modal-dismiss><section class="game-modal ${wide ? 'modal-wide' : ''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" type="button" data-modal-close aria-label="Close">×</button><h2 id="modal-title">${esc(title)}</h2>${content}</section></div>`;
131:   const backdrop = $('.modal-backdrop', root);
132:   backdrop.addEventListener('click', event => { if (event.target === backdrop || event.target.closest('[data-modal-close]')) closeModal(); });
133:   modalCleanup = event => { if (event.key === 'Escape') closeModal(); };
134:   document.addEventListener('keydown', modalCleanup);
135:   root.querySelector('input,select,button')?.focus();
136: }
137: function closeModal() {
138:   if (modalCleanup) document.removeEventListener('keydown', modalCleanup);
139:   modalCleanup = null;
140:   $('#modal-root').innerHTML = '';
141: }
142: const optionsHTML = (items, selected) => items.map(item => `<option value="${esc(item.id)}" ${item.id === selected ? 'selected' : ''}>${esc(item.name)}</option>`).join('');
143: function customizeResident(id) {
