147:   openModal(`Make ${r.name} feel like herself`, form, true);
148:   const formEl = $('#customize-form');
149:   const updatePreview = () => { const data = new FormData(formEl); const copy = { ...r, name: data.get('name') || r.name, style: Object.fromEntries(['hairStyle','hairColor','eyeColor','outfit','outfitColor','accessory'].map(key => [key, data.get(key)])) }; $('#customize-preview').innerHTML = portrait(copy); };
150:   formEl.addEventListener('input', updatePreview); formEl.addEventListener('change', updatePreview);
151:   formEl.addEventListener('submit', event => { event.preventDefault(); const data = new FormData(formEl); r.name = String(data.get('name')).trim().slice(0, 24) || r.name; r.bio = String(data.get('bio')).trim(); r.style = Object.fromEntries(['hairStyle','hairColor','eyeColor','outfit','outfitColor','accessory'].map(key => [key, data.get(key)])); save(); closeModal(); render(); showToast(`${r.name}’s new look is saved.`); });
152: }
153: function inviteResident() {
154:   if (state.residents.length >= 8) { showToast('Your home is full for now.'); return; }
155:   const form = `<form id="invite-form" class="modal-form"><p class="panel-kicker">Create an adult housemate and choose her style. You can edit her details later.</p><div class="customize-layout"><div class="customize-preview" id="invite-preview">${portrait({name:'New friend',style:{hairStyle:'wavy',hairColor:'mint',eyeColor:'teal',outfitColor:'blush',outfit:'dress',accessory:'flower'}})}</div><div class="customize-fields"><div class="form-grid"><label>Name<input name="name" maxlength="24" placeholder="e.g. Hikari" required></label><label>Age<input name="age" type="number" min="20" max="99" value="22" required></label><label>Role<input name="role" maxlength="36" placeholder="A new friend" value="A new friend"></label><label>Hair style<select name="hairStyle">${optionsHTML(HAIR_STYLES, 'wavy')}</select></label><label>Hair color<select name="hairColor">${optionsHTML(HAIR_COLORS, 'mint')}</select></label><label>Eye color<select name="eyeColor">${optionsHTML(EYE_COLORS, 'teal')}</select></label><label>Outfit<select name="outfit">${optionsHTML(OUTFITS, 'dress')}</select></label><label>Outfit color<select name="outfitColor">${optionsHTML(OUTFIT_COLORS, 'blush')}</select></label><label>Accessory<select name="accessory">${optionsHTML(ACCESSORIES, 'flower')}</select></label></div><label>About her<textarea name="bio" maxlength="180" rows="2" placeholder="A little about her personality…"></textarea></label><button class="primary-btn" type="submit">Invite her home</button></div></div></form>`;
156:   openModal('Welcome a new housemate', form, true);
157:   const formEl = $('#invite-form');
158:   const updatePreview = () => { const data = new FormData(formEl); const person = { name: data.get('name') || 'New friend', style: Object.fromEntries(['hairStyle','hairColor','eyeColor','outfit','outfitColor','accessory'].map(key => [key, data.get(key)])) }; $('#invite-preview').innerHTML = portrait(person); };
159:   formEl.addEventListener('input', updatePreview); formEl.addEventListener('change', updatePreview);
160:   formEl.addEventListener('submit', event => { event.preventDefault(); const data = new FormData(formEl); const name = String(data.get('name')).trim().slice(0, 24); if (!name) return; const id = `friend-${Date.now()}`; state.residents.push({ id, name, age: clamp(Number(data.get('age')), 20, 99), role: String(data.get('role') || 'A new friend').slice(0, 36), tagline: 'A new chapter in a shared home.', bio: String(data.get('bio') || 'Looking forward to getting to know everyone.').slice(0, 180), style: Object.fromEntries(['hairStyle','hairColor','eyeColor','outfit','outfitColor','accessory'].map(key => [key, data.get(key)])), affection: 10, mood: 70, energy: 75, comfort: 65, messages: [{ from: 'her', text: 'Thank you for making me feel welcome. I’m looking forward to sharing this home with you.', time: nowTime() }] }); addActivity('🌸', `${name} moved into Sakura House.`); save(); closeModal(); render(); showToast(`${name} is home!`); });
161: }
162: function showSettings() {
163:   const content = `<div class="settings-content"><p>Progress is saved in this browser on this device.</p><div class="settings-row"><div><b>Petals</b><small>Your shared household activity earns petals.</small></div><strong>✧ ${state.coins}</strong></div><div class="settings-actions"><button class="outline-btn" type="button" data-settings="export">Download save</button><button class="outline-btn" type="button" data-settings="reset">Start fresh</button></div><p class="panel-kicker">Starting fresh erases this local save and cannot be undone.</p></div>`;
164:   openModal('House settings', content);
165:   $$('[data-settings]', $('#modal-root')).forEach(button => button.addEventListener('click', () => {
166:     if (button.dataset.settings === 'export') {
167:       const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'sakura-house-save.json'; link.click(); URL.revokeObjectURL(url); showToast('Your save file is ready.');
168:     } else openModal('Start a fresh home?', `<p>This will permanently replace your current save on this device.</p><div class="modal-actions"><button class="outline-btn" data-modal-close type="button">Keep playing</button><button class="primary-btn" id="confirm-reset" type="button">Start fresh</button></div>`);
169:     $('#confirm-reset')?.addEventListener('click', () => { localStorage.removeItem(SAVE_KEY); state = freshState(); activeChatId = state.residents[0].id; closeModal(); setView('home'); showToast('A fresh week begins at home.'); });
170:   }));
171: }
172: function handleAction(action, id) {
173:   if (action === 'open-chat') return openChat(id);
174:   if (action === 'view-day') return setView('day');
175:   if (action === 'view-residents') return setView('residents');
176:   if (action === 'add-resident') return inviteResident();
177:   if (action === 'customize') return customizeResident(id);
178:   if (action === 'view-resident') return setView('residents');
179:   if (action === 'complete-task') {
