const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'], headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:8765/preview.html', { waitUntil: 'networkidle' });
  const previewResult = await page.evaluate(async () => {
    const { portraitSVG, SKIN_TONES } = await import('./js/portraits.js');
    const generated = SKIN_TONES.map(tone => portraitSVG({name:tone.name, style:{skinTone:tone.id}}));
    return { tones: SKIN_TONES.map(t => t.id), generated: generated.length, hasUniqueGradients: new Set(generated.map(svg => svg.match(/id="skin(\\d+)"/)?.[1])).size === generated.length, allHaveSkinGradient: generated.every(svg => svg.includes('stop-color=')) };
  });
  await page.screenshot({ path: '/tmp/opencode/sakura-portraits.png', fullPage: true });
  await page.goto('http://127.0.0.1:8765/', { waitUntil: 'networkidle' });
  await page.getByText('Housemates', { exact: true }).first().click();
  await page.getByRole('button', { name: /customize/i }).first().click().catch(() => {});
  const customizeHasTone = await page.locator('#customize-form select[name="skinTone"]').count();
  if (customizeHasTone) {
    await page.locator('#customize-form select[name="skinTone"]').selectOption('deep');
    await page.locator('#customize-form button[type="submit"]').click();
  }
  await page.locator('#add-resident').click();
  const inviteHasTone = await page.locator('#invite-form select[name="skinTone"]').count();
  if (inviteHasTone) {
    await page.locator('#invite-form select[name="skinTone"]').selectOption('umber');
    const hasUmbra = await page.locator('#invite-preview').innerHTML().then(html => html.includes('#573b35') || html.includes('#8f5d48'));
    await page.screenshot({ path: '/tmp/opencode/sakura-invite.png' });
    console.log(JSON.stringify({ previewResult, customizeHasTone, inviteHasTone, livePreviewChanged: hasUmbra, errors }, null, 2));
  } else console.log(JSON.stringify({ previewResult, customizeHasTone, inviteHasTone, errors }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });
