const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'], headless: true });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:8765/', { waitUntil: 'networkidle' });
  await page.locator('#add-resident').click();
  await page.locator('#invite-form input[name="name"]').fill('Skin Test');
  await page.locator('#invite-form select[name="skinTone"]').selectOption('golden');
  await page.locator('#invite-form button[type="submit"]').click();
  const saved = await page.evaluate(() => JSON.parse(localStorage.getItem('sakura-house-save-v1')).residents.find(r => r.name === 'Skin Test'));
  await page.reload({ waitUntil: 'networkidle' });
  const renderedSkin = await page.locator('svg').evaluateAll(svgs => svgs.some(svg => svg.outerHTML.includes('#c98e62')));
  console.log(JSON.stringify({ savedSkinTone: saved?.style?.skinTone, renderedAfterReload: renderedSkin, errors }, null, 2));
  await browser.close();
  if (saved?.style?.skinTone !== 'golden' || errors.length) process.exit(1);
})().catch(error => { console.error(error); process.exit(1); });
